const React=require('react'),{createRoot}=require('react-dom/client');
const {useConversationPages}=require('../../lib/inbox/use-conversation-pages.ts');
const {stableConversationOrder}=require('../../lib/inbox/stable-conversation-order.ts');
const {retainKnownConversationRows}=require('../../lib/inbox/retain-known-conversation-rows.ts');
const {useConversationListAnchor,captureConversationListAnchor}=require('../../lib/inbox/use-conversation-list-anchor.ts');
const uuid=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,business=uuid(900);
const seed=Array.from({length:80},(_,i)=>({id:uuid(i+1),business_id:business,status:'open',is_pinned:false,unread_count:i%2,updated_at:'2026-10-01T10:00:00Z',last_message_at:new Date(Date.UTC(2026,9,1,10,0,80-i)).toISOString(),last_message_text:'Seed '+i}));
let data=seed,calls=[],control;const request={status:'all',view:'all',search:'',channelId:null,workspaceId:null,workspaceContextId:business,cursor:null};
function page(body){const rows=stableConversationOrder([],data.filter(row=>body.view!=='unread'||row.unread_count>0));const first=rows.slice(0,30);return {conversations:first,updates:rows.filter(row=>body.knownIds?.includes(row.id)),matchedKnownIds:rows.filter(row=>body.knownIds?.includes(row.id)).map(row=>row.id),total:rows.length,hasMore:rows.length>30,cursor:{id:first.at(-1).id,pinned:false,lastMessageAt:first.at(-1).last_message_at},counts:{views:{all:data.length,unread:data.filter(row=>row.unread_count>0).length},statusCounts:{all:data.length},totalUnreadCount:40,unreadConversationCount:40},readTargets:[]};}
window.fetch=async(url,options)=>{if(url!=='/api/inbox/conversation-page')throw Error('Unexpected request');const body=JSON.parse(options.body);calls.push(body);return Response.json({success:true,page:page(body)});};
const initial={request,page:{...page(request),ids:seed.slice(0,30).map(row=>row.id)}};
function App(){const [live,setLive]=React.useState(seed),[view,setView]=React.useState('all');const body=React.useMemo(()=>({...request,view}),[view]);const pager=useConversationPages(initial,body,live);const a=React.useRef(null),b=React.useRef(null);const legacy=stableConversationOrder([],live.filter(row=>view!=='unread'||row.unread_count>0));useConversationListAnchor(a,view,JSON.stringify(legacy.map(row=>row.id)));useConversationListAnchor(b,view,JSON.stringify(pager.rows.map(row=>row.id)));control={setView,update:row=>{data=stableConversationOrder(data,[...data.filter(old=>old.id!==row.id),row]);setLive(old=>stableConversationOrder(old,[...old.filter(item=>item.id!==row.id),row]));},stale:()=>setLive(old=>retainKnownConversationRows(old,seed,[business],'',''))};const list=(id,ref,rows)=>React.createElement('div',{id,ref,style:{height:250,overflowY:'auto',overflowAnchor:'none',width:350,border:'1px solid'}},rows.map(row=>React.createElement('div',{key:row.id,'data-conversation-list-id':row.id,style:{height:100}},row.last_message_text)));return React.createElement(React.Fragment,null,list('legacy',a,legacy),list('paged',b,pager.rows),React.createElement('div',{id:'message-pane',style:{height:100,overflowY:'auto'}},React.createElement('div',{style:{height:1000}},'Independent message history')));}
const root=createRoot(document.getElementById('root'));root.render(React.createElement(App));
const pause=ms=>new Promise(r=>setTimeout(r,ms)),checks=[],check=(name,okay)=>{if(!okay)throw Error(name);checks.push(name);};
(async()=>{try{await pause(100);check('initial hydration issues no page read',calls.length===0);const legacy=document.getElementById('legacy'),paged=document.getElementById('paged'),message=document.getElementById('message-pane');legacy.scrollTop=350;paged.scrollTop=350;message.scrollTop=200;legacy.dispatchEvent(new Event('scroll'));paged.dispatchEvent(new Event('scroll'));await pause(50);const beforeA=captureConversationListAnchor(legacy),beforeB=captureConversationListAnchor(paged);control.update({...seed[79],last_message_at:'2026-10-01T12:00:00Z',updated_at:'2026-10-01T12:00:00Z',last_message_text:'Incoming latest'});await pause(550);check('incoming moves to first in legacy and paged list',legacy.firstElementChild.dataset.conversationListId===uuid(80)&&paged.firstElementChild.dataset.conversationListId===uuid(80));check('legacy reorder preserves visible anchor offset',captureConversationListAnchor(legacy).key===beforeA.key&&Math.abs(captureConversationListAnchor(legacy).offset-beforeA.offset)<1);check('paged reorder preserves visible anchor offset',captureConversationListAnchor(paged).key===beforeB.key&&Math.abs(captureConversationListAnchor(paged).offset-beforeB.offset)<1);check('list updates do not scroll independent message history',message.scrollTop===200);
 const customer={...seed[0],id:uuid(801),unread_count:1,last_message_at:'2026-10-01T13:00:00Z',updated_at:'2026-10-01T13:00:00Z',last_message_text:'New customer'};control.update(customer);await pause(500);control.setView('unread');await pause(100);check('new customer appears in Unread',legacy.textContent.includes('New customer')&&paged.textContent.includes('New customer'));control.stale();control.setView('all');await pause(150);check('new customer survives stale props and switch back to All',legacy.textContent.includes('New customer')&&paged.textContent.includes('New customer'));const count=calls.length;await pause(500);check('settled event-driven list does not poll',calls.length===count);check('qualification requests stay bounded',calls.every(body=>(body.knownIds?.length||0)<=200));document.getElementById('result').textContent=JSON.stringify({passed:true,checks,requests:calls.length});}catch(error){document.getElementById('result').textContent=JSON.stringify({passed:false,error:error.message,checks});}})();
